#include <stdio.h>

typedef struct {
    int largura;
    int altura;
} Retangulo;

/* os tres avisos sumiram juntos: a variavel que sobrava saiu, a ficha
   recebeu os DOIS campos e o parametro altura passou a ser usado. */
int zeroAvisos(int largura, int altura) {
    Retangulo r = {largura, altura};

    return r.largura * r.altura;
}
